void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    const float MIN = 0.001;
    const float SHAKE_INTENSITY = 0.002;

    vec2 uv = fragCoord/iResolution.xy;
    vec3 texCol0 = texture(iChannel0, uv).rgb;

    // red color intensity
    // float rci = dot(vec3(1,0,0), texCol0);
    float rci = texCol0.r;

    // lose color
    vec2 nuv = vec2(iTime * 0.3);
    float sa = texture(iChannel1, nuv).r;
    uv += max(sa * SHAKE_INTENSITY * mix(-1.0, 1.0, sa), MIN);
    vec3 texCol1 = -texture(iChannel0, uv).rgb * 0.666;

    fragColor = vec4(texCol0 + texCol1 + rci, 1);
}
